import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DOCUMENT_TYPES = ['작성 문서', '공유 문서', '공유받은 문서'];

// 가정: ECM 호출 수단이 없어 연계 저장은 문서의 ECM 식별자를 채우는 것으로 처리한다.
const ECM_ID_PREFIX = 'ECM-';

@Controller('api/v1')
export class FnSfr04107Controller {
  @Post('/office-documents/:officeDocumentId/link-ecm')
  @HttpCode(200)
  async linkOfficeDocumentToEcm(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const idText = req.params['officeDocumentId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT office_document_id AS "officeDocumentId" FROM office_document WHERE office_document_id = CAST(:id AS bigint)',
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '연계할 문서를 찾을 수 없습니다.');
      }
      const updated = await db.query(
        'UPDATE office_document SET ecm_document_id = COALESCE(ecm_document_id, :prefix || CAST(office_document_id AS varchar)), updated_at = now() WHERE office_document_id = CAST(:id AS bigint) RETURNING ecm_document_id AS "ecmDocumentId"',
        { id: idText, prefix: ECM_ID_PREFIX },
      );
      await db.execute(
        'INSERT INTO link_log (requester_id, link_target, link_type, status, requested_at, completed_at, processed_count, created_at, updated_at) VALUES (CAST(:userId AS bigint), :target, :linkType, :status, now(), now(), 1, now(), now())',
        { userId: user.id, target: 'ECM', linkType: '저장', status: 'SUCCESS' },
      );
      return { linked: true, ecmDocumentId: updated[0].ecmDocumentId };
    });
  }

  @Get('/ecm-documents')
  async listEcmDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.queryOf(req.query);
    const documentType = typeof data['documentType'] === 'string' ? data['documentType'] : '';
    if (!DOCUMENT_TYPES.includes(documentType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 구분을 선택해 주세요.');
    }
    const keyword = typeof data['keyword'] === 'string' ? data['keyword'].trim() : '';
    const page = data['page'] === undefined || data['page'] === '' ? 0 : Number(data['page']);
    const sizeRaw = data['size'] === undefined || data['size'] === '' ? 20 : Number(data['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기 형식이 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, 200);
    let scope: string;
    if (documentType === '작성 문서') {
      scope = 'd.author_id = CAST(:userId AS bigint)';
    } else if (documentType === '공유 문서') {
      scope = 'd.author_id = CAST(:userId AS bigint) AND EXISTS (SELECT 1 FROM office_document_share s WHERE s.office_document_id = d.office_document_id)';
    } else {
      scope = 'EXISTS (SELECT 1 FROM office_document_share s WHERE s.office_document_id = d.office_document_id AND s.employee_id = CAST(:userId AS bigint))';
    }
    // 조회 결과는 조회자의 권한 범위(작성자 또는 공유 대상)로 한정한다.
    const where = 'FROM office_document d WHERE ' + scope + " AND d.ecm_document_id IS NOT NULL AND (:keyword = '' OR d.title ILIKE '%' || :keyword || '%')";
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT d.office_document_id AS "officeDocumentId", d.title AS "title", d.ecm_document_id AS "ecmDocumentId", d.author_id AS "authorId" ' + where + ' ORDER BY d.office_document_id DESC LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        { userId: user.id, keyword, size, offset: page * size },
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" ' + where,
        { userId: user.id, keyword },
      );
      return { items: rows, page, size, total: Number(counted[0].total) };
    });
  }
}

