import { useState } from 'react';
import {
  call,
  useData,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  Select,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const DOCUMENT_TYPES: [string, string][] = [
  ['작성 문서', '작성 문서'],
  ['공유 문서', '공유 문서'],
  ['공유받은 문서', '공유받은 문서'],
];

export default function FnSfr04107Page({ role, notify }: PageProps) {
  const [documentType, setDocumentType] = useState('작성 문서');
  const [keyword, setKeyword] = useState('');
  const [applied, setApplied] = useState({ documentType: '작성 문서', keyword: '' });
  const [page, setPage] = useState(0);
  const [target, setTarget] = useState<Row | null>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/ecm-documents', role, undefined, { documentType: applied.documentType, keyword: applied.keyword, page, size: 20 }),
    [applied, page],
  );

  const search = () => {
    setPage(0);
    setApplied({ documentType, keyword });
  };

  const reset = () => {
    setDocumentType('작성 문서');
    setKeyword('');
    setPage(0);
    setApplied({ documentType: '작성 문서', keyword: '' });
  };

  const link = async () => {
    if (!target) return;
    await call('POST', '/office-documents/' + String(target['officeDocumentId']) + '/link-ecm', role, {});
    notify('ECM에 연계 저장했습니다.');
    setTarget(null);
    reload();
  };

  return (
    <div className="doc">
      <section className="box">
        <h2>ECM 문서 조회</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="문서 구분 (작성 문서, 공유 문서, 공유받은 문서)" required>
            <Select value={documentType} onChange={setDocumentType} options={DOCUMENT_TYPES} />
          </Field>
          <Field label="ECM 문서 조회 조건">
            <TextInput value={keyword} onChange={setKeyword} placeholder="문서 제목" />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          columns={[
            { key: 'title', label: '문서 제목' },
            { key: 'ecmDocumentId', label: 'ECM 문서 식별자' },
            { key: 'authorId', label: '작성자', render: (r) => <RefName table="employee" role={role} value={r['authorId']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) => (
                <button className="ghost" onClick={(e) => { e.stopPropagation(); setTarget(r); }}>
                  ECM 연계 저장
                </button>
              ),
            },
          ]}
          rows={data?.items ?? []}
          empty="조건에 맞는 ECM 문서가 없습니다. 문서 구분이나 조회 조건을 바꿔 보세요."
        />
        <Pager page={page} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {target ? (
        <Drawer title="웹 오피스 문서 ECM 연계 저장" onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['문서 제목', String(target['title'] ?? '')],
              ['ECM 문서 식별자', String(target['ecmDocumentId'] ?? '')],
            ]}
          />
          <Form onSubmit={link} submit="연계 저장" note="연계 결과는 연계 이력에 기록됩니다." />
        </Drawer>
      ) : null}
    </div>
  );
}
